210	const DERIVATIVE_ASSETS = /derivativ[^.;]{0,40}ativ(?!o? ?e)|ativ[^.;]{0,40}derivativ|derivative asset/;
211	
212	/**
213	 * The text of a definition must agree, operand by operand and side by side, with the formula the view
214	 * executes; a contradiction is a block, not a warning. The release view is debt less cash and investments;
215	 * the contractual view adds derivative liabilities and deducts derivative assets as well.
216	 */
217	function definitionDisagreement(name: "release" | "contractual", text: string): string | null {
218	  const parsed = parseDefinition(text);
219	  if (parsed.deducted === null) return `the ${name} definition never deducts anything; the view deducts cash and investments`;
220	  if (!DEBT.test(parsed.added)) return `the ${name} definition adds no debt line; the view sums loans, financings and debentures`;
221	  if (!DEBT_BASE_OK.test(parsed.added)) return `the ${name} definition does not add the whole debt base (loans, financings and debentures, or gross debt); the view sums all three`;
222	  if (FOREIGN.test(parsed.added) || FOREIGN.test(parsed.deducted)) return `the ${name} definition names a component that is not debt nor cash (${(FOREIGN.exec(parsed.added) ?? FOREIGN.exec(parsed.deducted))![0]}); the view has no such operand`;
223	  const deductedDebt = /emprestim|financiament|debenture|subordinad|divida bruta|gross debt|loan|borrowing/.exec(parsed.deducted.replace(/divida liquida|net debt/g, ""));
224	  if (deductedDebt) return `the ${name} definition deducts a debt operand (${deductedDebt[0]}); the view deducts only cash, investments and derivative assets`;
225	  if (!CASH.test(parsed.deducted)) return `the ${name} definition does not deduct cash; the view deducts cash and equivalents`;
226	  if (!INVESTMENTS.test(parsed.deducted)) return `the ${name} definition does not deduct financial investments; the view deducts them`;
227	  if (CASH.test(parsed.added) || INVESTMENTS.test(parsed.added)) return `the ${name} definition adds cash or investments; the view deducts them`;
228	  if (name === "release") {
229	    if (DERIVATIVES.test(plainText(text))) return "the release definition mentions derivatives; the release view executed excludes them";
230	    return null;
231	  }
232	  if (!DERIVATIVE_LIABILITIES.test(parsed.added)) return "the contractual definition does not add derivative liabilities; the contractual view executed adds them";
233	  if (!DERIVATIVE_ASSETS.test(parsed.deducted)) return "the contractual definition does not deduct derivative assets; the contractual view executed deducts them";
234	  if (DERIVATIVE_ASSETS.test(parsed.added)) return "the contractual definition adds derivative assets; the view deducts them";
235	  if (DERIVATIVE_LIABILITIES.test(parsed.deducted)) return "the contractual definition deducts derivative liabilities; the view adds them";
236	  return null;
237	}
238	const plainText = (text: string) => normalize(text);
239	
240	function canonical(input: z.infer<typeof debtLedgerInputSchema>) {
241	  return {
242	    ...input,
243	    rows: [...input.rows].sort((a, b) => compare(a.id, b.id)).map((row) => (row.obligation ? {...row, obligation: {...row.obligation, views: [...row.obligation.views].sort(compare)}} : row)),
244	    schedule: input.schedule ? {...input.schedule, periods: [...input.schedule.periods].sort((a, b) => compare(a.period, b.period))} : undefined,
245	  };
246	}
247	
248	/** JSON with object keys sorted at every level, so the fingerprint ignores the order a caller wrote its keys in. */
249	export const stableStringify = (value: unknown): string => JSON.stringify(value, (_key, inner: unknown) => (inner && typeof inner === "object" && !Array.isArray(inner) ? Object.fromEntries(Object.entries(inner as Record<string, unknown>).sort(([a], [b]) => compare(a, b))) : inner));
250	
251	export function buildDebtLedger(raw: DebtLedgerInput): DebtLedgerOutput {
252	  const input = canonical(debtLedgerInputSchema.parse(raw));
253	  const calculations: DebtLedgerOutput["trace"]["calculations"] = [];
254	  const record = (calculation: Omit<DebtLedgerOutput["trace"]["calculations"][number], "unit">) => calculations.push({...calculation, unit: input.unit});
255	  const rows = input.source === "release_only" ? [] : input.rows;
256	  const blockReasons: string[] = [];
257	  const incompleteReasons: string[] = [];
258	  const tolerance = d(input.tolerance.value);
259	  const toleranceOut = {value: input.tolerance.value, policyKey: input.tolerance.policyKey ?? null, policyVersion: input.tolerance.policyVersion ?? null};
260	
261	  const balances = Object.fromEntries(rows.map((row) => [row.id, row.balance]));
262	  const gross = rows.reduce((sum, row) => sum.plus(row.balance), d(0));
263	  // What the statements report as debt: the release view plus the contra lines; a row only an indenture includes stays out of the identity with the balance sheet.
264	  const reportedRows = rows.filter((row) => row.contra || row.obligation!.views.includes("release"));
265	  const contractualOnly = rows.filter((row) => !row.contra && !row.obligation!.views.includes("release"));
266	  const grossReported = reportedRows.reduce((sum, row) => sum.plus(row.balance), d(0));
267	  const grossBeforeContra = rows.filter((row) => !row.contra).reduce((sum, row) => sum.plus(row.balance), d(0));
268	  const priorKnown = rows.length > 0 && rows.every((row) => row.priorBalance !== null);
269	  const grossPrior = priorKnown ? rows.reduce((sum, row) => sum.plus(row.priorBalance!), d(0)) : null;
270	  record({id: "financial.debt_ledger_balance", formula: "sum(rows.balance)", operands: balances, result: out(gross)});
271	  record({id: "financial.debt_ledger_balance_reported", formula: "sum(rows.balance where row in release view or contra)", operands: Object.fromEntries(reportedRows.map((row) => [row.id, row.balance])), result: out(grossReported)});
272	  record({id: "financial.debt_ledger_balance_before_contra", formula: "sum(rows.balance where not contra)", operands: Object.fromEntries(rows.filter((row) => !row.contra).map((row) => [row.id, row.balance])), result: out(grossBeforeContra)});
273	  if (grossPrior) record({id: "financial.debt_ledger_balance_prior", formula: "sum(rows.priorBalance)", operands: Object.fromEntries(rows.map((row) => [row.id, row.priorBalance!])), result: out(grossPrior)});
274	
275	  if (input.source === "release_only") blockReasons.push("only a release is in the base; a ledger needs the debt note of the financial statements, so no row is produced");
276	  if (input.source === "note" && rows.length === 0 && !input.noDebtEvidence) blockReasons.push("no rows and no evidence that the company has no onerous debt: silence is not an empty ledger");
277	  if (input.source === "note" && rows.length === 0 && input.noDebtEvidence && !input.balanceSheet) blockReasons.push("the base claims no onerous debt but no balance sheet proves a zero balance; an empty ledger needs the balance sheet");
278	  if (input.noDebtEvidence && rows.length > 0) blockReasons.push("the base claims no onerous debt and the note carries rows; the contradiction blocks the ledger");
279	  if (rows.length === 0 && input.noDebtEvidence && input.balanceSheet && !d(input.balanceSheet.current).plus(input.balanceSheet.nonCurrent).isZero()) {
280	    blockReasons.push("the base claims no onerous debt but the balance sheet carries debt totals; the contradiction blocks the ledger");
281	  }
282	
283	  let reconciliation: DebtLedgerOutput["reconciliation"] = {total: {state: "not_possible", balanceSheetTotal: null, difference: null}, split: {state: "not_possible", currentDifference: null, nonCurrentDifference: null, reason: "no balance sheet in the base"}, tolerance: toleranceOut, anchor: null};
284	  if (input.balanceSheet && rows.length > 0) {
285	    const sheetCurrent = d(input.balanceSheet.current);
286	    const sheetNonCurrent = d(input.balanceSheet.nonCurrent);
287	    const total = sheetCurrent.plus(sheetNonCurrent);
288	    const difference = grossReported.minus(total);
289	    const within = difference.abs().lte(tolerance);
290	    record({id: "financial.accounting_identity", formula: "sum(reported rows.balance) - (balanceSheet.current + balanceSheet.nonCurrent)", operands: {ledgerReported: out(grossReported), contractualOnly: out(gross.minus(grossReported)), balanceSheetCurrent: out(sheetCurrent), balanceSheetNonCurrent: out(sheetNonCurrent), tolerance: input.tolerance.value}, result: out(difference)});

